@Test
public void testEmbeddedServerIdentifier_defaultAndSet_1_oe() {
    Object a = EmbeddedServers.defaultIdentifier();
    assertEquals("Should return defaultIdentifier()", a, service.embeddedServerIdentifier());
}

mut_docstring:
/**
     * Set the identifier used to select the EmbeddedServer;
     * null for the default.
     *
     * @param obj the identifier passed to {@link EmbeddedServers}.
     */

mut_method_definition:
public synchronized void embeddedServerIdentifier(Object obj) {
        if (initialized) {
            throwBeforeRouteMappingException();
        }
        embeddedServerIdentifier = obj;
    }

