@Test
public void testIsParam_whenParameterFormattedAsParm_1_oe() throws Exception {

    boolean a = SparkUtils.isParam(":param");
    assertTrue("Should return true because parameter follows convention of a parameter(:paramname)", a);
}

mut_method_definition:
public static boolean isParam(String routePart) {
        return routePart.startsWith(":");
    }

test_prefix:
@Test
public void testIsParam_whenParameterNotFormattedAsParm_1_oe() throws Exception {

    boolean a = SparkUtils.isParam(".param");
    assertFalse("Should return false because parameter does not follows convention of a parameter(:paramname)", a);
}

mut_method_definition:
public static boolean isParam(String routePart) {
        return routePart.startsWith(":");
    }

