@Test
public void testIsSplat_whenParameterIsASplat_1_oe() throws Exception {

    boolean a = SparkUtils.isSplat("*");
    assertTrue("Should return true because parameter is a splat (*)", a);
}

mut_method_definition:
public static boolean isSplat(String routePart) {
        return routePart.equals("*");
    }

test_prefix:
@Test
public void testIsSplat_whenParameterIsNotASplat_1_oe() throws Exception {

    boolean a = SparkUtils.isSplat("!");
    assertFalse("Should return true because parameter is not a splat (*)", a);
}

mut_method_definition:
public static boolean isSplat(String routePart) {
        return routePart.equals("*");
    }

